css:
body :where([data-bz-node="cx"]) .bz-block{padding:0}
body :where([data-bz-node="cx"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="cx"]>.bz-container{padding-inline:0}

body [data-bz-node="cx-h"] .bz-eyebrow{font:700 10.5px/1.4 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:#6b6b6a;margin:0 0 14px}
body [data-bz-node="cx-h"] h2{font:700 36px/1.08 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="cx-h"] h2:empty{display:none}
body [data-bz-node="cx-intro"] .bz-text{max-width:760px;margin-top:22px}
body [data-bz-node="cx-intro"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0;margin:0 0 14px}
body [data-bz-node="cx-intro"] p:last-child{margin:0}
body [data-bz-node="cx-intro"] a{color:var(--accent);text-decoration:none}

body [data-bz-node="cx"]{background:#fff;padding:96px 0}
body [data-bz-node="cx"]>.bz-container{max-width:var(--container)}
body [data-bz-node="cx-grid"]{display:grid;grid-template-columns:repeat(2,1fr);gap:24px;margin-top:40px;align-items:stretch}
body [data-bz-node="cx-grid"]:empty{display:none}
body [data-bz-node="cx-grid"]>.bz-col{grid-column:auto}
body [data-bz-node^="cx-card-"]{display:flex;flex-direction:column;background:#fff;border:1px solid #e4e4e2;padding:30px 30px 32px;box-sizing:border-box}
body [data-bz-node^="cx-title-"] h3{font:700 15px/1.35 var(--font-heading);letter-spacing:.01em;text-transform:uppercase;color:var(--ink);margin:0 0 16px}
body [data-bz-node^="cx-title-"] h3:empty{display:none}
body [data-bz-node^="cx-para-"]{display:block;margin-bottom:12px}
body [data-bz-node^="cx-para-"] p,body [data-bz-node^="cx-after-"] p{font:400 12.5px/1.75 var(--font-body);color:#555;margin:0}
body [data-bz-node^="cx-para-"] a,body [data-bz-node^="cx-after-"] a{color:var(--accent);text-decoration:none}
body [data-bz-node^="cx-pt-"]{display:block;margin-bottom:8px}
body [data-bz-node^="cx-pt-"] p{position:relative;padding-left:18px;font:400 12.5px/1.75 var(--font-body);color:#555;margin:0}
body [data-bz-node^="cx-pt-"] p::before{content:"";position:absolute;left:1px;top:9px;width:6px;height:6px;background:var(--accent)}
body [data-bz-node^="cx-after-"]{margin-top:6px}
body [data-bz-node^="cx-link-"]{margin-top:auto;padding-top:18px}
body [data-bz-node^="cx-link-"] .bz-btns{margin:0}
body [data-bz-node^="cx-link-"] .bz-btn{padding:0;border:0;background:none;color:var(--ink);font:700 10.5px/1 var(--font-body);letter-spacing:.16em;text-transform:uppercase;text-decoration:none;gap:10px;height:auto;min-height:0}
body [data-bz-node^="cx-link-"] .bz-btn::after{content:"";width:13px;height:13px;background:currentColor;-webkit-mask:url(/icons/arrow-right.svg) center/13px no-repeat;mask:url(/icons/arrow-right.svg) center/13px no-repeat}
body [data-bz-node^="cx-link-"] .bz-btn:hover{color:var(--accent)}
body [data-bz-node="cx-outro-h"]{margin-top:56px}
body [data-bz-node="cx-outro-h"] h3{font:700 26px/1.1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="cx-outro-h"] h3:empty{display:none}
body [data-bz-node="cx-outro"] .bz-text{max-width:none;margin-top:18px}
body [data-bz-node="cx-outro"] p{font:400 13.5px/25px var(--font-body);color:var(--ink);margin:0}
@media (max-width:1100px){body [data-bz-node="cx"]{padding:64px 24px}body [data-bz-node="cx-grid"]{grid-template-columns:1fr 1fr}body [data-bz-node="cx-h"] h2{font-size:30px}}
@media (max-width:820px){body [data-bz-node="cx-grid"]{grid-template-columns:1fr}}
@media (max-width:640px){body [data-bz-node="cx"]{padding:48px 20px}body [data-bz-node="cx-h"] h2{font-size:26px}body [data-bz-node="cx-grid"]{gap:16px;margin-top:28px}body [data-bz-node^="cx-card-"]{padding:24px 22px 26px}body [data-bz-node="cx-outro-h"] h3{font-size:22px}}
